export interface Project {
  /** Catalogue number from the vault note; the label code is `SDJ-<catalog>` and higher is newer. */
  catalog: number;
  slug: string;
  title: string;
  summary: string;
  year: string;
  status: string;
  format: string;
  collaborators: string;
  recordCover: string;
  ogCover: string;
  coverUrl: string;
  coverAlt: string;
  backCoverUrl?: string;
  backCoverAlt?: string;
  outboundUrl: string | null;
  /**
   * CSS background approximating the front cover's colours, shown until the artwork or its blurred backdrop
   * loads (generated by `npm run sync:vault`).
   */
  placeholder: string;
  /** Same, from the back cover; present exactly when `backCoverUrl` is. */
  backPlaceholder?: string;
  /** Average cover colour (hex), for surfaces that can't use a gradient (WebGL sleeves; generated). */
  coverColor: string;
  content?: string;
}

/** The crate's "older works" sleeve, standing in for releases beyond the featured ones. Colours as on `Project`. */
export interface OlderWorksSleeve {
  coverUrl: string;
  coverColor: string;
  placeholder: string;
  backCoverUrl?: string;
  backPlaceholder?: string;
}
